1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import dayjs from "dayjs";
3	import { useMemo } from "react";
4	import { type MemoTimeBasis, useView } from "@/contexts/ViewContext";
5	import { State } from "@/types/proto/api/v1/common_pb";
6	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
7	
8	export interface UseMemoSortingOptions {
9	  pinnedFirst?: boolean;
10	  state?: State;
11	}
12	
13	export interface UseMemoSortingResult {
14	  listSort: (memos: Memo[]) => Memo[];
15	  orderBy: string;
16	}
17	
18	const getMemoSortTime = (memo: Memo, timeBasis: MemoTimeBasis): Date | undefined => {
19	  const timestamp = timeBasis === "update_time" ? memo.updateTime : memo.createTime;
20	  return timestamp ? timestampDate(timestamp) : undefined;
21	};
22	
23	// Moves the memo with the given name to the front of the list, above pinned
24	// memos, so a freshly created memo is immediately visible. Returns the input
25	// unchanged when the name is null, absent, or already first.
26	export const hoistMemoToFront = (memos: Memo[], name: string | null): Memo[] => {
27	  if (!name) return memos;
28	  const index = memos.findIndex((memo) => memo.name === name);
29	  if (index <= 0) return memos;
30	  const reordered = memos.slice();
31	  const [memo] = reordered.splice(index, 1);
32	  reordered.unshift(memo);
33	  return reordered;
34	};
35	
36	export const useMemoSorting = (options: UseMemoSortingOptions = {}): UseMemoSortingResult => {
37	  const { pinnedFirst = false, state = State.NORMAL } = options;
38	  const { orderByTimeAsc, timeBasis } = useView();
39	
40	  // Generate orderBy string for API
41	  const orderBy = useMemo(() => {
42	    const timeOrder = orderByTimeAsc ? `${timeBasis} asc` : `${timeBasis} desc`;
43	    return pinnedFirst ? `pinned desc, ${timeOrder}` : timeOrder;
44	  }, [pinnedFirst, orderByTimeAsc, timeBasis]);
45	
46	  // Generate listSort function for client-side sorting
47	  const listSort = useMemo(() => {
48	    return (memos: Memo[]): Memo[] => {
49	      return memos
50	        .filter((memo) => memo.state === state)
51	        .sort((a, b) => {
52	          // First, sort by pinned status if enabled
53	          if (pinnedFirst && a.pinned !== b.pinned) {
54	            return b.pinned ? 1 : -1;
55	          }
56	
57	          // Then sort by the selected time field.
58	          const aTime = getMemoSortTime(a, timeBasis);
59	          const bTime = getMemoSortTime(b, timeBasis);
60	          return orderByTimeAsc ? dayjs(aTime).unix() - dayjs(bTime).unix() : dayjs(bTime).unix() - dayjs(aTime).unix();
61	        });
62	    };
63	  }, [pinnedFirst, state, orderByTimeAsc, timeBasis]);
64	
65	  return { listSort, orderBy };
66	};
