8	import type { Visibility } from "@/types/proto/api/v1/memo_service_pb";
9	import { useTranslate } from "@/utils/i18n";
10	import { errorService, memoService, validationService } from "../services";
11	import { useEditorContext } from "../state";
12	
13	interface UseMemoSaveOptions {
14	  memoName?: string;
15	  parentMemoName?: string;
16	  defaultVisibility?: Visibility;
17	  defaultCreateTime?: Date;
18	  discardDraft: () => void;
19	  onConfirm?: (memoName: string) => void;
20	  onCancel?: () => void;
21	}
